using EZapi;
using EZapi.Registration;
using System.Text;
using System.Text.Json;
var cases=new List<object>();int passed=0,failed=0;
void Test(string name,Func<bool> test){RegistrationApi.Stop();RegistrationApi.Start();ItemRegistry.TooLate=false;try{if(!test())throw new Exception("assertion false");cases.Add(new{name,passed=true});passed++;}catch(Exception ex){cases.Add(new{name,passed=false,error=ex.ToString()});failed++;}}
bool Throws(Action action,string code){try{action();return false;}catch(Exception ex){return ex.Message.Contains(code,StringComparison.Ordinal);}}
SubmitResult Register(string owner,string version="1.0.0",Action<RegistrationBatch>? callback=null)=>RegistrationApi.Register(owner,version,callback??(_=>{}));
RegistrationBatch Parse(string json){using var stream=new MemoryStream(Encoding.UTF8.GetBytes(json));return JsonRegistration.Parse(stream);}
SubmitResult Json(string json){using var stream=new MemoryStream(Encoding.UTF8.GetBytes(json));return RegistrationApi.RegisterJson(stream);}
string Basic(string extras="")=>"{\"ownerId\":\"author.test\",\"version\":\"1.0.0\""+extras+"}";

Test("empty batch resolves as metadata only",()=>Register("author.test").Status==SubmitStatus.Accepted&&RegistrationApi.IsResolved("author.test")&&RegistrationApi.Snapshot().Single().DefinitionIds.Count==0);
Test("all public definition kinds accepted",()=>{Register("author.test",callback:b=>{foreach(var kind in Enum.GetValues<DefinitionKind>())b.Define(kind,kind.ToString().ToLowerInvariant(),"contract-v1");});return RegistrationApi.Snapshot().Single().DefinitionIds.Count==7&&RegistrationApi.IsResolved("author.test");});
Test("local IDs gain owner namespace",()=>{Register("author.test",callback:b=>b.Define(DefinitionKind.Item,"sensor","v1"));return RegistrationApi.Snapshot().Single().DefinitionIds.Single()=="author.test.sensor";});
Test("owned full ID not double-prefixed",()=>{Register("author.test",callback:b=>b.Define(DefinitionKind.Item,"author.test.sensor","v1"));return RegistrationApi.Snapshot().Single().DefinitionIds.Single()=="author.test.sensor";});
Test("missing dependency waits then resolves on provider submit",()=>{Register("author.addon",callback:b=>b.Require("author.base","1.2.0"));var old=RegistrationApi.Snapshot().Single();Register("author.base","1.2.0");return old.Status==RegistrationStatus.Waiting&&old.Reason.Contains("missing owner")&&RegistrationApi.IsResolved("author.addon");});
Test("too-old dependency stays waiting with reason",()=>{Register("author.base","1.1.9");Register("author.addon",callback:b=>b.Require("author.base","1.2.0"));return !RegistrationApi.IsResolved("author.addon")&&RegistrationApi.Snapshot().Single(v=>v.OwnerId=="author.addon").Reason.Contains(">=1.2.0");});
Test("dependency versions compare numerically",()=>{Register("author.base","1.10.0");Register("author.addon",callback:b=>b.Require("author.base","1.9.99"));return RegistrationApi.IsResolved("author.addon");});
Test("transitive dependency resolves entire chain",()=>{Register("author.a",callback:b=>b.Require("author.b"));Register("author.b",callback:b=>b.Require("author.c"));var waiting=RegistrationApi.Snapshot().All(v=>v.Status==RegistrationStatus.Waiting);Register("author.c");return waiting&&RegistrationApi.Snapshot().All(v=>v.Status==RegistrationStatus.DependenciesResolved);});
Test("owner dependency cycle remains waiting",()=>{Register("author.a",callback:b=>b.Require("author.b"));Register("author.b",callback:b=>b.Require("author.a"));return RegistrationApi.Snapshot().All(v=>v.Status==RegistrationStatus.Waiting&&v.Reason.Contains("unresolved or cyclic"));});
Test("empty provider batch satisfies declared owner version",()=>{Register("author.base");Register("author.addon",callback:b=>b.Require("author.base"));return RegistrationApi.IsResolved("author.addon");});
Test("own forward definition references resolve after whole-batch commit",()=>{Register("author.test",callback:b=>b.Define(DefinitionKind.Module,"module","v1","author.test.effect").Define(DefinitionKind.Effect,"effect","v1"));return RegistrationApi.IsResolved("author.test");});
Test("missing own definition leaves entire batch waiting",()=>{Register("author.test",callback:b=>b.Define(DefinitionKind.Module,"module","v1","author.test.missing"));return !RegistrationApi.IsResolved("author.test")&&RegistrationApi.Snapshot().Single().Reason.Contains("missing definition author.test.missing");});
Test("local definition cycle remains waiting",()=>{Register("author.test",callback:b=>b.Define(DefinitionKind.Item,"a","v1","author.test.b").Define(DefinitionKind.Item,"b","v1","author.test.a"));return !RegistrationApi.IsResolved("author.test");});
Test("cross-owner ID reference waits for complete provider",()=>{Register("author.addon",callback:b=>b.Define(DefinitionKind.Item,"x","v1","author.base.y"));Register("author.base",callback:b=>b.Require("author.third").Define(DefinitionKind.Item,"y","v1"));var wait=!RegistrationApi.IsResolved("author.addon");Register("author.third");return wait&&RegistrationApi.IsResolved("author.addon");});
Test("cross-owner definition cycle detected without explicit Require",()=>{Register("author.a",callback:b=>b.Define(DefinitionKind.Item,"x","v1","author.b.y"));Register("author.b",callback:b=>b.Define(DefinitionKind.Item,"y","v1","author.a.x"));return RegistrationApi.Snapshot().All(v=>v.Status==RegistrationStatus.Waiting);});
Test("dependency diamond resolves independent of submission order",()=>{Register("author.top",callback:b=>b.Require("author.left").Require("author.right"));Register("author.left",callback:b=>b.Require("author.base"));Register("author.right",callback:b=>b.Require("author.base"));Register("author.base");return RegistrationApi.Snapshot().All(v=>v.Status==RegistrationStatus.DependenciesResolved);});
Test("unrelated batch does not wait on other owner's cycle",()=>{Register("author.a",callback:b=>b.Require("author.b"));Register("author.b",callback:b=>b.Require("author.a"));Register("author.independent");return RegistrationApi.IsResolved("author.independent");});
Test("identical replay returns AlreadyPresent",()=>{Register("author.test",callback:b=>b.Define(DefinitionKind.Item,"x","v1"));return Register("author.test",callback:b=>b.Define(DefinitionKind.Item,"x","v1")).Status==SubmitStatus.AlreadyPresent&&RegistrationApi.Snapshot().Count==1;});
Test("declaration order does not change replay identity",()=>{Register("author.test",callback:b=>b.Require("author.a").Require("author.b").Define(DefinitionKind.Item,"x","v1","author.a.x","author.b.x").Define(DefinitionKind.Status,"y","v1"));return Register("author.test",callback:b=>b.Define(DefinitionKind.Status,"y","v1").Define(DefinitionKind.Item,"x","v1","author.b.x","author.a.x").Require("author.b").Require("author.a")).Status==SubmitStatus.AlreadyPresent;});
Test("replay full and local IDs equivalent",()=>{Register("author.test",callback:b=>b.Define(DefinitionKind.Item,"x","v1"));return Register("author.test",callback:b=>b.Define(DefinitionKind.Item,"author.test.x","v1")).Status==SubmitStatus.AlreadyPresent;});
foreach(var change in new[]{"version","kind","signature","references","dependency","definitions"})Test("changed "+change+" rejects replay without altering existing",()=>{
 Register("author.test",callback:b=>b.Define(DefinitionKind.Item,"x","v1"));
 var result=Register("author.test",change=="version"?"2.0.0":"1.0.0",b=>{b.Define(change=="kind"?DefinitionKind.Module:DefinitionKind.Item,"x",change=="signature"?"v2":"v1",change=="references"?new[]{"author.base.x"}:Array.Empty<string>());if(change=="dependency")b.Require("author.base");if(change=="definitions")b.Define(DefinitionKind.Node,"y","v1");});
 var view=RegistrationApi.Snapshot().Single();return result.Status==SubmitStatus.Conflict&&view.Version=="1.0.0"&&view.DefinitionIds.Count==1&&RegistrationApi.IsResolved("author.test");
});
Test("namespace collision rejects whole new batch",()=>{Register("author",callback:b=>b.Define(DefinitionKind.Item,"child.x","v1"));var result=Register("author.child",callback:b=>b.Define(DefinitionKind.Item,"y","v1").Define(DefinitionKind.Item,"x","v1"));return result.Status==SubmitStatus.Conflict&&RegistrationApi.Snapshot().Count==1;});
Test("duplicate definition in callback submits nothing",()=>Register("author.test",callback:b=>b.Define(DefinitionKind.Item,"x","v1").Define(DefinitionKind.Module,"x","v1")).Status==SubmitStatus.Invalid&&RegistrationApi.Snapshot().Count==0);
Test("callback exception does not leak earlier definitions",()=>{var result=Register("author.test",callback:b=>{b.Define(DefinitionKind.Item,"x","v1");throw new Exception("author failure");});return result.Status==SubmitStatus.Invalid&&result.Reason.Contains("author failure")&&RegistrationApi.Snapshot().Count==0;});
Test("failed batch does not reserve ID or owner",()=>{Register("author.test",callback:b=>{b.Define(DefinitionKind.Item,"x","v1");throw new Exception();});return Register("author.test",callback:b=>b.Define(DefinitionKind.Item,"x","v1")).Status==SubmitStatus.Accepted;});
Test("batch callback cannot observe partial submission",()=>{var count=-1;Register("author.test",callback:b=>{b.Define(DefinitionKind.Item,"x","v1");count=RegistrationApi.Snapshot().Count;});return count==0&&RegistrationApi.Snapshot().Count==1;});
Test("nested registration refused without leaking inner batch",()=>{SubmitResult? inner=null;Register("author.test",callback:b=>{inner=Register("author.inner");b.Define(DefinitionKind.Item,"x","v1");});return inner?.Status==SubmitStatus.Invalid&&inner.Reason.Contains("REENTRY")&&RegistrationApi.Snapshot().Count==1;});
Test("captured callback batch sealed after successful submit",()=>{RegistrationBatch? retained=null;Register("author.test",callback:b=>retained=b);return Throws(()=>retained!.Define(DefinitionKind.Item,"late","v1"),"SEALED");});
Test("captured callback batch sealed after callback failure",()=>{RegistrationBatch? retained=null;Register("author.test",callback:b=>{retained=b;throw new Exception();});return Throws(()=>retained!.Require("author.base"),"SEALED");});
Test("caller required ID array copied immediately",()=>{var ids=new[]{"author.base.x"};var batch=new RegistrationBatch("author.test","1.0.0").Define(DefinitionKind.Item,"x","v1",ids);ids[0]="author.missing.x";RegistrationApi.Register(batch);Register("author.base",callback:b=>b.Define(DefinitionKind.Item,"x","v1"));return RegistrationApi.IsResolved("author.test");});
Test("read-only snapshot list cannot mutate catalog",()=>{Register("author.test");return Throws(()=>((IList<RegistrationView>)RegistrationApi.Snapshot()).Clear(),"read-only");});
Test("snapshot definition list rejects writes",()=>{Register("author.test",callback:b=>b.Define(DefinitionKind.Item,"x","v1"));return Throws(()=>((IList<string>)RegistrationApi.Snapshot().Single().DefinitionIds)[0]="changed","read-only");});
Test("prior snapshot stable after resolution",()=>{Register("author.test",callback:b=>b.Require("author.base"));var old=RegistrationApi.Snapshot().Single();Register("author.base");return old.Status==RegistrationStatus.Waiting&&RegistrationApi.IsResolved("author.test");});
Test("snapshots sorted deterministically",()=>{Register("z");Register("a",callback:b=>b.Define(DefinitionKind.Item,"z","v1").Define(DefinitionKind.Item,"a","v1"));return RegistrationApi.Snapshot().Select(v=>v.OwnerId).SequenceEqual(new[]{"a","z"})&&RegistrationApi.Snapshot()[0].DefinitionIds.SequenceEqual(new[]{"a.a","a.z"});});
Test("off-thread registration refuses before callback",()=>{bool invoked=false;var result=Task.Run(()=>Register("author.test",callback:b=>invoked=true)).GetAwaiter().GetResult();return result.Status==SubmitStatus.Invalid&&!invoked&&RegistrationApi.Snapshot().Count==0;});
Test("off-thread snapshot rejected",()=>Task.Run(()=>Throws(()=>RegistrationApi.Snapshot(),"THREAD")).GetAwaiter().GetResult());
Test("too-late registration never executes callback",()=>{ItemRegistry.TooLate=true;bool invoked=false;return Register("author.test",callback:b=>invoked=true).Status==SubmitStatus.Invalid&&!invoked;});
Test("phase change during callback rejects batch",()=>Register("author.test",callback:b=>ItemRegistry.TooLate=true).Status==SubmitStatus.Invalid&&RegistrationApi.Snapshot().Count==0);
Test("shutdown during callback rejects batch",()=>{var result=Register("author.test",callback:b=>RegistrationApi.Stop());RegistrationApi.Start();return result.Status==SubmitStatus.Invalid&&RegistrationApi.Snapshot().Count==0;});
Test("restart during callback invalidates previous generation",()=>{var result=Register("author.test",callback:b=>{RegistrationApi.Stop();RegistrationApi.Start();});return result.Status==SubmitStatus.Invalid&&result.Reason.Contains("STALE")&&RegistrationApi.Snapshot().Count==0;});
Test("stop clears catalog and restart permits clean submission",()=>{Register("author.test");RegistrationApi.Stop();RegistrationApi.Start();return RegistrationApi.Snapshot().Count==0&&Register("author.test","2.0.0").Status==SubmitStatus.Accepted;});
Test("uninitialized register refused",()=>{RegistrationApi.Stop();return Register("author.test").Status==SubmitStatus.Invalid;});
Test("null callback invalid",()=>RegistrationApi.Register("author.test","1.0.0",null!).Status==SubmitStatus.Invalid&&RegistrationApi.Snapshot().Count==0);
Test("batch builder rejects cross-thread changes",()=>{var batch=new RegistrationBatch("author.test","1.0.0");var rejected=Task.Run(()=>Throws(()=>batch.Define(DefinitionKind.Item,"x","v1"),"THREAD")).GetAwaiter().GetResult();return rejected&&RegistrationApi.Register(batch).Accepted&&RegistrationApi.Snapshot().Single().DefinitionIds.Count==0;});
Test("batch built on other thread rejected at submit",()=>{var batch=Task.Run(()=>new RegistrationBatch("author.test","1.0.0")).GetAwaiter().GetResult();return RegistrationApi.Register(batch).Status==SubmitStatus.Invalid&&RegistrationApi.Snapshot().Count==0;});
foreach(var owner in new[]{""," ","Author","a/b","a\\b","a..b","a\n",new string('a',161)})Test("bad owner "+JsonSerializer.Serialize(owner),()=>Register(owner).Status==SubmitStatus.Invalid&&RegistrationApi.Snapshot().Count==0);
foreach(var version in new[]{"","1","1.0","1.0.0.0","01.0.0","1.0.0-beta","1.0.0\n","1.9999999999.0","-1.0.0"})Test("bad version "+JsonSerializer.Serialize(version),()=>Register("author.test",version).Status==SubmitStatus.Invalid);
foreach(var kind in new[]{(DefinitionKind)(-1),(DefinitionKind)7})Test("undefined kind "+kind,()=>Register("author.test",callback:b=>b.Define(kind,"x","v1")).Status==SubmitStatus.Invalid);
foreach(var id in new[]{"","X","a/b","a..b","x\n",new string('a',161)})Test("bad local ID "+JsonSerializer.Serialize(id),()=>Register("author.test",callback:b=>b.Define(DefinitionKind.Item,id,"v1")).Status==SubmitStatus.Invalid);
foreach(var signature in new[]{""," ","x\ny",new string('s',4097)})Test("bad signature "+signature.Length,()=>Register("author.test",callback:b=>b.Define(DefinitionKind.Item,"x",signature)).Status==SubmitStatus.Invalid);
Test("max signature length accepted",()=>Register("author.test",callback:b=>b.Define(DefinitionKind.Item,"x",new string('s',4096))).Accepted);
Test("self owner dependency invalid",()=>Register("author.test",callback:b=>b.Require("author.test")).Status==SubmitStatus.Invalid);
Test("duplicate owner dependency invalid",()=>Register("author.test",callback:b=>b.Require("author.base").Require("author.base")).Status==SubmitStatus.Invalid);
Test("self definition dependency invalid",()=>Register("author.test",callback:b=>b.Define(DefinitionKind.Item,"x","v1","author.test.x")).Status==SubmitStatus.Invalid);
Test("duplicate required definition invalid",()=>Register("author.test",callback:b=>b.Define(DefinitionKind.Item,"x","v1","author.base.x","author.base.x")).Status==SubmitStatus.Invalid);
Test("unqualified required definition invalid",()=>Register("author.test",callback:b=>b.Define(DefinitionKind.Item,"x","v1","x")).Status==SubmitStatus.Invalid);
Test("500 definitions supported",()=>Register("author.test",callback:b=>{for(var i=0;i<500;i++)b.Define(DefinitionKind.Item,"item"+i,"v1");}).Accepted&&RegistrationApi.Snapshot().Single().DefinitionIds.Count==500);
Test("501 definitions rejects whole callback",()=>Register("author.test",callback:b=>{for(var i=0;i<501;i++)b.Define(DefinitionKind.Item,"item"+i,"v1");}).Status==SubmitStatus.Invalid&&RegistrationApi.Snapshot().Count==0);
Test("65 owner dependencies reject whole callback",()=>Register("author.test",callback:b=>{for(var i=0;i<65;i++)b.Require("dependency"+i);}).Status==SubmitStatus.Invalid);
Test("65 definition references rejected",()=>Register("author.test",callback:b=>b.Define(DefinitionKind.Item,"x","v1",Enumerable.Range(0,65).Select(i=>"dependency.item"+i).ToArray())).Status==SubmitStatus.Invalid);
Test("owner count limit preserves existing directory",()=>{for(var i=0;i<256;i++)if(!Register("owner"+i).Accepted)return false;return Register("extra").Status==SubmitStatus.Invalid&&RegistrationApi.Snapshot().Count==256;});
Test("large definition graph resolves without recursion",()=>{var catalog=new RegistrationCatalog();for(var batch=0;batch<16;batch++){var b=new RegistrationBatch("owner"+batch,"1.0.0");for(var i=0;i<500;i++)b.Define(DefinitionKind.Item,"item"+i,"v1",i==0?Array.Empty<string>():new[]{"owner"+batch+".item"+(i-1)});if(!catalog.Submit(b).Accepted)return false;}return catalog.Snapshot().Count==16&&catalog.Snapshot().All(v=>v.Status==RegistrationStatus.DependenciesResolved);});
Test("global definition limit rejects atomic overflow",()=>{var catalog=new RegistrationCatalog();for(var j=0;j<16;j++){var b=new RegistrationBatch("owner"+j,"1.0.0");for(var i=0;i<500;i++)b.Define(DefinitionKind.Item,"i"+i,"v1");catalog.Submit(b);}var extra=new RegistrationBatch("extra","1.0.0");for(var i=0;i<193;i++)extra.Define(DefinitionKind.Item,"i"+i,"v1");return catalog.Submit(extra).Status==SubmitStatus.Invalid&&catalog.Snapshot().Count==16;});

Test("minimal JSON batch accepted",()=>Json(Basic()).Accepted&&RegistrationApi.IsResolved("author.test"));
Test("JSON full declaration and dependency resolution",()=>{var result=Json(Basic(",\"dependencies\":[{\"ownerId\":\"author.base\",\"minimumVersion\":\"1.0.0\"}],\"definitions\":[{\"kind\":\"Module\",\"localId\":\"m\",\"signature\":\"v1\",\"requiredIds\":[\"author.base.e\"]}]"));Register("author.base",callback:b=>b.Define(DefinitionKind.Effect,"e","v1"));return result.Accepted&&RegistrationApi.IsResolved("author.test");});
Test("JSON parsed batch sealed",()=>Throws(()=>Parse(Basic()).Require("author.base"),"SEALED"));
Test("JSON equivalent to C# replay",()=>{Register("author.test",callback:b=>b.Define(DefinitionKind.Item,"x","v1"));return Json(Basic(",\"definitions\":[{\"kind\":\"item\",\"localId\":\"x\",\"signature\":\"v1\"}]")).Status==SubmitStatus.AlreadyPresent;});
foreach(var text in new[]{"[]","null","{}",Basic(",\"extra\":1"),Basic(",\"version\":\"1.0.0\""),Basic(",\"definitions\":null"),Basic(",\"definitions\":{}"),Basic(",\"dependencies\":[null]"),Basic(",\"dependencies\":[{\"ownerId\":\"base\",\"extra\":1}]"),Basic(",\"dependencies\":[{\"ownerId\":\"base\",\"minimumVersion\":null}]"),Basic(",\"definitions\":[{\"kind\":1,\"localId\":\"x\",\"signature\":\"v1\"}]"),Basic(",\"definitions\":[{\"kind\":\"1\",\"localId\":\"x\",\"signature\":\"v1\"}]"),Basic(",\"definitions\":[{\"kind\":\"Unknown\",\"localId\":\"x\",\"signature\":\"v1\"}]"),Basic(",\"definitions\":[{\"kind\":\"Item\",\"localId\":\"x\",\"signature\":\"v1\",\"requiredIds\":[1]}]"),Basic(",\"definitions\":[{\"kind\":\"Item\",\"localId\":\"x\"}]"),Basic(",\"definitions\":[{\"kind\":\"Item\",\"localId\":\"x\",\"signature\":\"v1\",\"signature\":\"v2\"}]"),Basic(",\"Definitions\":[]")})Test("strict JSON rejects "+text,()=>Json(text).Status==SubmitStatus.Invalid&&RegistrationApi.Snapshot().Count==0);
Test("JSON byte limit rejected before submitting",()=>{using var stream=new MemoryStream(Encoding.UTF8.GetBytes(Basic()+new string(' ',2*1024*1024)));return RegistrationApi.RegisterJson(stream).Status==SubmitStatus.Invalid&&RegistrationApi.Snapshot().Count==0;});
var result=new{passed,failed,cases,scope="real managed declaration graph, public registration adapter and strict JSON parser; no native content application or save claims"};
Directory.CreateDirectory("work");File.WriteAllText("work/registration-tests-0.1.52.json",JsonSerializer.Serialize(result));Console.WriteLine(JsonSerializer.Serialize(new{passed,failed,errors=cases.Where(c=>JsonSerializer.Serialize(c).Contains("\"passed\":false"))}));Environment.ExitCode=failed==0?0:1;
